  "settings.tuya.regionSg": { id: "Singapore (Indonesia/Malaysia/Thailand/Vietnam)", en: "Singapore (Indonesia/Malaysia/Thailand/Vietnam)", ms: "Singapura (Indonesia/Malaysia/Thailand/Vietnam)", th: "สิงคโปร์ (อินโดนีเซีย/มาเลเซีย/ไทย/เวียดนาม)", fil: "Singapore (Indonesia/Malaysia/Thailand/Vietnam)", vi: "Singapore (Indonesia/Malaysia/Thái Lan/Việt Nam)" },
