  "settings.durationPreset.minutesRequiredAlert": { id: "Isi durasi dalam menit (lebih dari 0).", en: "Enter the duration in minutes (greater than 0).", ms: "Isi tempoh dalam minit (lebih daripada 0).", th: "กรอกระยะเวลาเป็นนาที (มากกว่า 0)", fil: "Ilagay ang tagal sa minuto (higit sa 0).", vi: "Nhập thời lượng theo phút (lớn hơn 0)." },
  "settings.durationPreset.labelRequiredAlert": { id: "Isi nama tampilan durasi.", en: "Enter the duration's display name.", ms: "Isi nama paparan tempoh.", th: "กรอกชื่อที่แสดงของระยะเวลา", fil: "Ilagay ang display name ng tagal.", vi: "Nhập tên hiển thị của thời lượng." },
  "settings.durationPreset.deleteConfirm": {
    id: 'Hapus preset "{label}"? Sesi yang sudah berjalan dengan durasi ini tidak terpengaruh, hanya hilang dari pilihan ke depannya.',
    en: 'Delete the preset "{label}"? Sessions already running with this duration are unaffected — it just disappears from the picker going forward.',
    ms: 'Padam praset "{label}"? Sesi yang sudah berjalan dengan tempoh ini tidak terjejas, ia hanya hilang daripada pilihan pada masa hadapan.',
    th: 'ลบพรีเซ็ต "{label}" หรือไม่? เซสชันที่กำลังทำงานอยู่ด้วยระยะเวลานี้จะไม่ได้รับผลกระทบ แค่จะหายไปจากตัวเลือกในครั้งต่อไป',
    fil: 'Burahin ang preset na "{label}"? Hindi maaapektuhan ang mga session na tumatakbo na sa tagal na ito, mawawala lang ito sa pagpipilian sa susunod.',
    vi: 'Xóa mốc "{label}"? Các phiên đang chạy với thời lượng này không bị ảnh hưởng, chỉ biến mất khỏi danh sách chọn sau này.',
  },
