  "settings.durationPreset.labelPlaceholder": { id: "Nama tampilan (mis. 45 menit)", en: "Display name (e.g. 45 minutes)", ms: "Nama paparan (cth. 45 minit)", th: "ชื่อที่แสดง (เช่น 45 นาที)", fil: "Display name (hal. 45 minuto)", vi: "Tên hiển thị (vd. 45 phút)" },
