  "settings.feature.superuserOnly": { id: "Feature Management hanya bisa diakses oleh Superuser.", en: "Feature Management can only be accessed by Superuser.", ms: "Pengurusan Ciri hanya boleh diakses oleh Superuser.", th: "การจัดการฟีเจอร์เข้าถึงได้เฉพาะ Superuser เท่านั้น", fil: "Feature Management ay maa-access lang ng Superuser.", vi: "Chỉ Superuser mới có thể truy cập Quản lý tính năng." },
  "settings.feature.explainer": {
    id: "Aktif/nonaktifkan modul di sini kapan saja tanpa menghapus data — histori transaksi, jurnal accounting, deposit, dan laporan lama tetap tersimpan dan bisa diakses lagi begitu modul diaktifkan kembali.",
    en: "Turn modules on/off here anytime without deleting data — transaction history, accounting journals, deposits, and old reports stay saved and become accessible again as soon as the module is re-enabled.",
    ms: "Aktif/nyahaktifkan modul di sini pada bila-bila masa tanpa memadam data — sejarah transaksi, jurnal perakaunan, deposit, dan laporan lama kekal tersimpan dan boleh diakses semula sebaik sahaja modul diaktifkan semula.",
    th: "เปิด/ปิดโมดูลที่นี่ได้ตลอดเวลาโดยไม่ลบข้อมูล — ประวัติธุรกรรม สมุดรายวันบัญชี เงินมัดจำ และรายงานเก่ายังคงถูกบันทึกไว้และสามารถเข้าถึงได้อีกครั้งทันทีที่เปิดใช้งานโมดูลอีกครั้ง",
    fil: "I-on/off ang mga module dito anumang oras nang hindi binubura ang data — mananatiling naka-save ang transaction history, accounting journal, deposit, at lumang report at maa-access ulit sa sandaling i-enable muli ang module.",
    vi: "Bật/tắt mô-đun tại đây bất cứ lúc nào mà không xóa dữ liệu — lịch sử giao dịch, sổ nhật ký kế toán, tiền đặt cọc và báo cáo cũ vẫn được lưu và có thể truy cập lại ngay khi mô-đun được bật lại.",
  },
  "settings.feature.on": { id: "ON", en: "ON", ms: "ON", th: "เปิด", fil: "ON", vi: "BẬT" },
  "settings.feature.off": { id: "OFF", en: "OFF", ms: "OFF", th: "ปิด", fil: "OFF", vi: "TẮT" },
