  "settings.tv.field.rentalUnit": { id: "Unit rental (TV Android)", en: "Rental unit (Android TV)", ms: "Unit sewaan (TV Android)", th: "เครื่องให้เช่า (Android TV)", fil: "Rental unit (Android TV)", vi: "Máy cho thuê (Android TV)" },
  "settings.tv.noUnitOption": { id: "— tanpa unit (branding saja) —", en: "— no unit (branding only) —", ms: "— tanpa unit (penjenamaan sahaja) —", th: "— ไม่ผูกเครื่อง (แสดงแบรนด์เท่านั้น) —", fil: "— walang unit (branding lang) —", vi: "— không gắn máy (chỉ thương hiệu) —" },
