  "settings.tv.smartPlugCheck": { id: "smart plug, perlu dicek", en: "smart plug, needs checking", ms: "palam pintar, perlu disemak", th: "สมาร์ทปลั๊ก ต้องตรวจสอบ", fil: "smart plug, kailangang suriin", vi: "ổ cắm thông minh, cần kiểm tra" },
  "settings.tv.addScreen": { id: "Tambah Layar", en: "Add Screen", ms: "Tambah Skrin", th: "เพิ่มจอ", fil: "Magdagdag ng Screen", vi: "Thêm màn hình" },
  "settings.tv.noUnitHint": { id: "\"Tanpa unit\" untuk TV Android yang bukan bilik — area tunggu atau etalase — dan hanya menampilkan branding, harga, dan QR booking.", en: "\"No unit\" is for Android TVs that aren't in a booth — a waiting area or display — and only shows branding, prices, and the booking QR.", ms: "\"Tanpa unit\" untuk TV Android yang bukan di bilik — ruang menunggu atau paparan — dan hanya memaparkan penjenamaan, harga, dan QR tempahan.", th: "\"ไม่ผูกเครื่อง\" สำหรับ Android TV ที่ไม่ได้อยู่ในห้อง — เช่น พื้นที่รอหรือหน้าร้าน — และแสดงเฉพาะแบรนด์ ราคา และ QR จอง", fil: "Ang \"walang unit\" ay para sa Android TV na wala sa booth — waiting area o display — at branding, presyo, at booking QR lang ang ipinapakita.", vi: "\"Không gắn máy\" dành cho Android TV không ở trong phòng — khu chờ hoặc quầy trưng bày — và chỉ hiển thị thương hiệu, giá và QR đặt chỗ." },
  "settings.tv.noScreens": { id: "Belum ada layar terpasang.", en: "No screens installed yet.", ms: "Belum ada skrin terpasang.", th: "ยังไม่มีจอที่ติดตั้ง", fil: "Wala pang naka-install na screen.", vi: "Chưa có màn hình nào được lắp." },
