  "settings.tv.auto.unavailable": { id: "Otomatisasi mulai/selesai sesi: tidak tersedia —", en: "Session start/end automation: not available —", ms: "Automasi mula/tamat sesi: tidak tersedia —", th: "ระบบอัตโนมัติเริ่ม/จบเซสชัน: ไม่พร้อมใช้งาน —", fil: "Automation ng simula/tapos ng session: hindi available —", vi: "Tự động hóa bắt đầu/kết thúc phiên: không khả dụng —" },
  "settings.tv.auto.confirmTest": { id: "Tes ini benar-benar mengubah tampilan TV. Pastikan bilik ini sedang TIDAK dipakai pelanggan. Lanjutkan?", en: "This test really changes what the TV shows. Make sure this booth is NOT being used by a customer. Continue?", ms: "Ujian ini benar-benar mengubah paparan TV. Pastikan bilik ini TIDAK sedang digunakan pelanggan. Teruskan?", th: "การทดสอบนี้จะเปลี่ยนสิ่งที่แสดงบนทีวีจริง ตรวจให้แน่ใจว่าไม่มีลูกค้าใช้ห้องนี้อยู่ ดำเนินการต่อไหม?", fil: "Talagang binabago ng test na ito ang ipinapakita ng TV. Tiyaking HINDI ginagamit ng customer ang booth na ito. Ituloy?", vi: "Bài kiểm tra này thực sự thay đổi màn hình TV. Hãy chắc chắn phòng này KHÔNG có khách đang dùng. Tiếp tục?" },
  "settings.tv.auto.testFailed": { id: "Tes gagal dijalankan.", en: "The test could not be run.", ms: "Ujian gagal dijalankan.", th: "ไม่สามารถเรียกใช้การทดสอบได้", fil: "Hindi napatakbo ang test.", vi: "Không chạy được bài kiểm tra." },
  "settings.tv.auto.serverUnreachable": { id: "Tidak bisa menghubungi server.", en: "Could not reach the server.", ms: "Tidak dapat menghubungi pelayan.", th: "ติดต่อเซิร์ฟเวอร์ไม่ได้", fil: "Hindi makakonekta sa server.", vi: "Không kết nối được máy chủ." },
