  "settings.tv.auto.title": { id: "Otomatisasi sesi (Relay Agent)", en: "Session automation (Relay Agent)", ms: "Automasi sesi (Relay Agent)", th: "ระบบอัตโนมัติของเซสชัน (Relay Agent)", fil: "Automation ng session (Relay Agent)", vi: "Tự động hóa phiên (Relay Agent)" },
  "settings.tv.auto.version": { id: "versi", en: "version", ms: "versi", th: "เวอร์ชัน", fil: "bersyon", vi: "phiên bản" },
  "settings.tv.auto.online": { id: "online", en: "online", ms: "dalam talian", th: "ออนไลน์", fil: "online", vi: "trực tuyến" },
  "settings.tv.auto.offline": { id: "offline", en: "offline", ms: "luar talian", th: "ออฟไลน์", fil: "offline", vi: "ngoại tuyến" },
  "settings.tv.auto.howItWorks": { id: "Saat aktif: sesi selesai → TV membuka screensaver NEXBILL; sesi mulai → TV pindah ke HDMI PlayStation. Kalau salah satu gagal, sesi tetap jalan dan kasir mendapat peringatan.", en: "When active: session ends → the TV opens the NEXBILL screensaver; session starts → the TV switches to the PlayStation HDMI. If either fails, the session keeps running and the cashier gets a warning.", ms: "Apabila aktif: sesi tamat → TV membuka penyelamat skrin NEXBILL; sesi bermula → TV beralih ke HDMI PlayStation. Jika salah satu gagal, sesi tetap berjalan dan juruwang menerima amaran.", th: "เมื่อเปิดใช้: เซสชันจบ → ทีวีเปิดสกรีนเซฟเวอร์ NEXBILL เซสชันเริ่ม → ทีวีสลับไปที่ HDMI ของ PlayStation หากอย่างใดอย่างหนึ่งล้มเหลว เซสชันยังดำเนินต่อและแคชเชียร์จะได้รับคำเตือน", fil: "Kapag aktibo: tapos ang session → bubuksan ng TV ang NEXBILL screensaver; simula ang session → lilipat ang TV sa HDMI ng PlayStation. Kung pumalya ang isa, tuloy pa rin ang session at makakatanggap ng babala ang kahera.", vi: "Khi bật: phiên kết thúc → TV mở màn hình chờ NEXBILL; phiên bắt đầu → TV chuyển sang HDMI PlayStation. Nếu một trong hai thất bại, phiên vẫn chạy và thu ngân nhận cảnh báo." },
  "settings.tv.field.hdmiPort": { id: "1. PlayStation dicolok di HDMI", en: "1. PlayStation is plugged into HDMI", ms: "1. PlayStation dipasang pada HDMI", th: "1. PlayStation เสียบที่ HDMI", fil: "1. Nakasaksak ang PlayStation sa HDMI", vi: "1. PlayStation cắm vào HDMI" },
  "settings.tv.auto.choose": { id: "— pilih —", en: "— choose —", ms: "— pilih —", th: "— เลือก —", fil: "— pumili —", vi: "— chọn —" },
  "settings.tv.field.browser": { id: "Browser di TV (opsional)", en: "Browser on the TV (optional)", ms: "Pelayar di TV (pilihan)", th: "เบราว์เซอร์บนทีวี (ไม่บังคับ)", fil: "Browser sa TV (opsyonal)", vi: "Trình duyệt trên TV (tùy chọn)" },
  "settings.tv.auto.defaultBrowser": { id: "Browser bawaan TV", en: "TV's default browser", ms: "Pelayar lalai TV", th: "เบราว์เซอร์เริ่มต้นของทีวี", fil: "Default na browser ng TV", vi: "Trình duyệt mặc định của TV" },
  "settings.tv.auto.browserPlaceholder": { id: "kosongkan = browser bawaan", en: "leave empty = default browser", ms: "kosongkan = pelayar lalai", th: "เว้นว่าง = เบราว์เซอร์เริ่มต้น", fil: "iwanang blangko = default na browser", vi: "để trống = trình duyệt mặc định" },
  "settings.tv.auto.detect": { id: "Deteksi TV", en: "Detect TV", ms: "Kesan TV", th: "ตรวจหาทีวี", fil: "I-detect ang TV", vi: "Phát hiện TV" },
  "settings.tv.auto.detected": { id: "TV terdeteksi:", en: "TV detected:", ms: "TV dikesan:", th: "ตรวจพบทีวี:", fil: "Na-detect na TV:", vi: "Đã phát hiện TV:" },
  "settings.tv.auto.detectFailed": { id: "Deteksi gagal:", en: "Detection failed:", ms: "Pengesanan gagal:", th: "ตรวจหาไม่สำเร็จ:", fil: "Nabigo ang pag-detect:", vi: "Phát hiện thất bại:" },
  "settings.tv.auto.sameBrowser": { id: "Pilih browser yang SAMA dengan yang dipakai saat pairing di nexbill.id/tv — kalau berbeda, TV akan meminta kode pairing lagi setiap kali sesi selesai.", en: "Choose the SAME browser used when pairing at nexbill.id/tv — if it's different, the TV will ask for the pairing code again every time a session ends.", ms: "Pilih pelayar yang SAMA dengan yang digunakan semasa pemasangan di nexbill.id/tv — jika berbeza, TV akan meminta kod pemasangan lagi setiap kali sesi tamat.", th: "เลือกเบราว์เซอร์เดียวกับที่ใช้ตอนจับคู่ที่ nexbill.id/tv — หากต่างกัน ทีวีจะขอรหัสจับคู่ใหม่ทุกครั้งที่เซสชันจบ", fil: "Piliin ang PAREHONG browser na ginamit sa pag-pair sa nexbill.id/tv — kung iba, hihingi ulit ang TV ng pairing code tuwing matatapos ang session.", vi: "Chọn CÙNG trình duyệt đã dùng khi ghép nối ở nexbill.id/tv — nếu khác, TV sẽ hỏi lại mã ghép nối mỗi khi phiên kết thúc." },
  "settings.tv.auto.step2": { id: "2. Tes di TV sungguhan — jalankan saat bilik kosong, lalu LIHAT layar TV-nya.", en: "2. Test on the real TV — run it while the booth is empty, then LOOK at the TV screen.", ms: "2. Uji di TV sebenar — jalankan semasa bilik kosong, kemudian LIHAT skrin TV.", th: "2. ทดสอบกับทีวีจริง — ทำตอนห้องว่าง แล้วดูที่จอทีวี", fil: "2. I-test sa totoong TV — patakbuhin habang walang tao ang booth, saka TINGNAN ang screen ng TV.", vi: "2. Thử trên TV thật — chạy khi phòng trống, rồi NHÌN màn hình TV." },
  "settings.tv.auto.testScreensaver": { id: "Tes buka screensaver", en: "Test opening the screensaver", ms: "Uji buka penyelamat skrin", th: "ทดสอบเปิดสกรีนเซฟเวอร์", fil: "I-test ang pagbukas ng screensaver", vi: "Thử mở màn hình chờ" },
  "settings.tv.auto.testHdmi": { id: "Tes pindah ke HDMI {port}", en: "Test switching to HDMI {port}", ms: "Uji beralih ke HDMI {port}", th: "ทดสอบสลับไป HDMI {port}", fil: "I-test ang paglipat sa HDMI {port}", vi: "Thử chuyển sang HDMI {port}" },
  "settings.tv.auto.screensaverSent": { id: "Perintah terkirim. Lihat TV-nya: apakah screensaver NEXBILL terbuka, tanpa diminta kode pairing?", en: "Command sent. Look at the TV: did the NEXBILL screensaver open without asking for a pairing code?", ms: "Arahan dihantar. Lihat TV: adakah penyelamat skrin NEXBILL terbuka tanpa diminta kod pemasangan?", th: "ส่งคำสั่งแล้ว ดูที่ทีวี: สกรีนเซฟเวอร์ NEXBILL เปิดขึ้นโดยไม่ขอรหัสจับคู่ไหม?", fil: "Naipadala ang utos. Tingnan ang TV: bumukas ba ang NEXBILL screensaver nang hindi humihingi ng pairing code?", vi: "Đã gửi lệnh. Nhìn TV: màn hình chờ NEXBILL có mở mà không hỏi mã ghép nối không?" },
